Future<void> main()async{
 WidgetsFlutterBinding.ensureInitialized();
 const demo=bool.fromEnvironment('DEMO');
 String? failure;
 if(!demo){try{await Firebase.initializeApp(options:DefaultFirebaseOptions.currentPlatform);}catch(e){failure=e is StateError?e.message.toString():'Firebase could not initialize. Check your platform configuration.';}}
